cture" dir="rtl" lang="ar">سَيْفٌ</span><span class="rule-table-ru">меч</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ جَامِدٌ غَيْرُ مُشْتَقٍّ</span><span class="rule-table-ru">непроизводное имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَأْسٌ</span><span class="rule-table-ru">топор</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ جَامِدٌ غَيْرُ مُشْتَقٍّ</span><span class="rule-table-ru">непроизводное имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَلَمٌ</span><span class="rule-table-ru">письменная трость; ручка</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ جَامِدٌ غَيْرُ مُشْتَقٍّ</span><span class="rule-table-ru">непроизводное имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رُمْحٌ</span><span class="rule-table-ru">копьё</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ جَامِدٌ غَيْرُ مُشْتَقٍّ</span><span class="rule-table-ru">непроизводное имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">دِرْعٌ</span><span class="rule-table-ru">щит; доспех</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ جَامِدٌ غَيْرُ مُشْتَقٍّ</span><span class="rule-table-ru">непроизводное имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">شَوْكَةٌ</span><span class="rule-table-ru">вилка</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ جَامِدٌ غَيْرُ مُشْتَقٍّ</span><span class="rule-table-ru">непроизводное имя</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Замечание автора</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْبَصْرِيُّونَ يَرَوْنَ أَنَّ أَصْلَ الْمُشْتَقَّاتِ هُوَ الْمَصْدَرُ وَلَيْسَ الْفِعْلَ.</span><p class="rule-study-text">Басрийские грамматисты считают источником производных слов масдар, а не глагол.</p></div></div>', 1, 'rule', 'Имя орудия обозначает предмет, посредством которого совершается действие; шарх приводит три основные модели, три позднее признанные модели и непроизводные названия.', 'اسْمُ الْآلَةِ اسْمٌ مَصُوغٌ لِلدَّلَالَةِ عَلَى مَا وَقَعَ الْفِعْلُ بِوَاسِطَتِهِ. يُشْتَقُّ مِنَ الْفِعْلِ الثُّلَاثِيِّ الْمُجَرَّدِ عَلَى ثَلَاثَةِ أَوْزَانٍ: مِفْعَالٍ، وَمِفْعَلٍ، وَمِفْعَلَةٍ. وَأَقَرَّ الْمُحْدَثُونَ أَوْزَانًا أُخْرَى، وَوَرَدَتْ أَسْمَاءُ آلَةٍ جَامِدَةٌ لَا أَفْعَالَ لَهَا.');
  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'اسمُ الآلَةِ
اسمُ الآلَةِ : اسمٌ مَصُوغٌ لِلدَّلاَلةِ على ما وَقَعَ الفعلُ بواسطتِه .
صِيَاغَتُهُ : اسمُ الآلةِ مُشتقٌّ من الفعلِ الثلاثيِّ المجرَّدِ ، ويُصَاغُ على ثلاثةِ أوزانٍ :
1- مِفْعَالٌ ، نحو : فَتَحَ يَفْتَحُ : مِفْتَاحٌ .           قَاسَ يَقِيسُ : مِقْيَاسٌ .
زَلَجَ يَزْلِجُ : مِزْلاَجٌ .          وَزَنَ يَزِنُ : مِيزَانٌ . أصله ( مِوْزَان ) .
2- مِفْعَلٌ ، نحو :  بَرَدَ يَبْرُدُ : مِبْرَدٌ .             قَادَ يَقُودُ : مِقْوَدٌ .
صَعِدَ يَصْعَدُ : مِصْعَدٌ .        قَصَّ يَقُصُّ : مِقَصٌّ . أصله ( مِقْصَصٌ ).
3- مِفْعَلَةٌ ، نحو : كَنَسَ يَكْنُسُ : مِكْنَسَةٌ .      قَلَى يَقْلِي : مِقَلاَةٌ . أصله ( مِقْلَيَةٌ ) .
كَوَى يَكْوِي : مِكْوَاةٌ .      مَحَا يَمْحُو : مِمْحَاةٌ. أصله ( مِمْحَوَةٌ ).
-------------------------------------------------
* أَقَرَّ الْمُحْدَثُونَ أوزاناً أُخْرَى ، هي :
1- فَاعِلَة ، نحو : سَاقِيَة .
2- فَاعُول ، نحو : سَاطُور .
3- فَعَّالَة ، نحو : ثَلاَّجَة .
* وَرَدَتْ أسماء آلة ليست لها أفعال ، فهي أسماء جَامِدَة غير مُشْتَقَّة ، نحو :
سِكّين ، سَيْف ، فَأْس ، قَلَم ، رُمْح ، دِرْع ، شَوْكَة .
-------------------------------------------------
* الْبَصْرِيُّونَ يَرَوْنَ أَنَّ أصْلَ الْمُشْتَقَّاتِ ، هو : الْمَصْدَرُ وليسَ الفِعل .', 34, 35, 1 from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '7' and sort_order = 1;
  select count(*) into new_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '7';
  select count(*) into source_count from public.rule_sources rs join public.rules r on r.id = rs.rule_id where r.course_name = 'Мединский курс (Том 3)' and r.lesson_number = '7';
  if new_rule_count <> 1 or source_count <> 1 then raise exception 'Book 3 lesson 7 verification failed: rules %, sources %', new_rule_count, source_count; end if;
end
$migration$;
commit;
